    gw_window = SDL_CreateWindow(
        "COBOL Doom  |  W/S move  A/D turn  1/2 switch  Space fire  Q/Esc quit",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        gw_screen_width,
        gw_screen_height,
        window_flags
