    if (!gw_window) {
        fprintf(stderr, "SDL window failed: %s\n", SDL_GetError());
        SDL_Quit();
        return;
    }

    gw_renderer = SDL_CreateRenderer(gw_window, -1, renderer_flags);
    if (!gw_renderer) {
        gw_renderer = SDL_CreateRenderer(gw_window, -1, SDL_RENDERER_SOFTWARE);
    }
    if (!gw_renderer) {
        fprintf(stderr, "SDL renderer failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(gw_window);
