static void draw_number(int x, int y, int scale, int value, int digits, Uint8 r, Uint8 g, Uint8 b, Uint8 a) {
    int place = 1;
    const int step = (12 * scale) + (4 * scale);

    if (value < 0) {
        value = 0;
    }

    for (int idx = 1; idx < digits; ++idx) {
        place *= 10;
    }

    for (int idx = 0; idx < digits; ++idx) {
        int digit = (value / place) % 10;
        draw_seven_segment_digit(x + (idx * step), y, scale, digit, r, g, b, a);
        if (place > 1) {
            place /= 10;
        }
    }
}

